package com.myeshopping.ordergroup;
import org.springframework.boot.*; import org.springframework.boot.autoconfigure.*; import org.springframework.web.bind.annotation.*; import java.util.*;
@SpringBootApplication @RestController @RequestMapping("/api/v1/order-groups") public class OrderGroupApplication { private final Map<String,Map<String,Object>> groups=new HashMap<>(); public static void main(String[]a){SpringApplication.run(OrderGroupApplication.class,a);} @PostMapping public Map<String,Object> group(@RequestParam Long customerId,@RequestParam String deliveryDate,@RequestBody List<Long> orderIds){String key=customerId+":"+deliveryDate;return groups.computeIfAbsent(key,k->{Map<String,Object>g=new LinkedHashMap<>();g.put("customerId",customerId);g.put("deliveryDate",deliveryDate);g.put("orderIds",new ArrayList<>(orderIds));g.put("status","GROUPED");return g;});} @GetMapping public Collection<Map<String,Object>> all(){return groups.values();} }
